CREATE TABLE admin_audit (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, actor_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, target_user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, action VARCHAR(40) NOT NULL, data JSON NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (id), KEY admin_audit_recent_idx (created_at), KEY admin_audit_target_idx (target_user_id,created_at), CONSTRAINT admin_audit_actor_fk FOREIGN KEY (actor_id) REFERENCES users(id) ON DELETE SET NULL, CONSTRAINT admin_audit_target_fk FOREIGN KEY (target_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci